import { initDataCloudSdk } from '../src/index';
import nock from 'nock';
import { RequiredError } from "../src/lib/runtime";
import {expect} from "@jest/globals";



describe('SDK initialization', () => {
    beforeEach(nock.cleanAll);
    beforeAll(nock.cleanAll);

    const TEST_TENANT_ID = "tenant-id";
    const TEST_APPSOURCE_ID = "appid";

    it('initDataCloudSdk happy path.',() => {
        expect(() => {
            const client = initDataCloudSdk(TEST_TENANT_ID, TEST_APPSOURCE_ID);
        }).not.toThrow();
    });

    it('initDataCloudSdk throws if tenant id is not provided.',() => {
        expect(() => {
            const client = initDataCloudSdk("", TEST_APPSOURCE_ID);
        }).toThrow(RequiredError);
    });

    it('initDataCloudSdk throws if app source id is not provided.',() => {
        expect(() => {
            const client = initDataCloudSdk(TEST_TENANT_ID, "");
        }).toThrow(RequiredError);
    });
});